    8.5.0

     Ora supporta l'associazione di socket della famiglia AF_PACKET.




    8.5.0

     Ora lancia un ValueError quando
     port è minore di 0 o maggiore di 65535.


   &sockets.changelog.socket-param;

  &reftitle.examples;



    Uso di socket_bind per impostare l'indirizzo di origine


<?php
// Crea un nuovo socket
$sock = socket_create(AF_INET, SOCK_STREAM, SOL_TCP);

// Un elenco di esempio di indirizzi IP posseduti dal computer
$sourceips['kevin']    = '127.0.0.1';
$sourceips['madcoder'] = '127.0.0.2';

// Associa l'indirizzo di origine
socket_bind($sock, $sourceips['madcoder']);

// Connessione all'indirizzo di destinazione
socket_connect($sock, '127.0.0.1', 80);

// Scrittura
$request = 'GET / HTTP/1.1' . "\r\n" .
           'Host: example.com' . "\r\n\r\n";
socket_write($sock, $request);

// Chiusura
socket_close($sock);

?>

&reftitle.notes;



  Questa funzione deve essere usata sul socket prima di
  socket_connect.
